-- Relational data only: a dependency's advisories move out of a jsonb column
-- (`advisories`) and a text[] column (`vulnerabilities`) into tables.
-- Generated by drizzle-kit, then hand-edited: the statements are reordered and
-- the three INSERT … SELECT statements copy the existing data across before the
-- old columns are dropped.
ALTER TABLE "app_dependencies" ADD CONSTRAINT "app_dependencies_id_workspace_unique" UNIQUE("id","workspace_id");--> statement-breakpoint
CREATE TABLE "dependency_advisories" (
	"id" uuid PRIMARY KEY NOT NULL,
	"workspace_id" uuid NOT NULL,
	"dependency_id" uuid NOT NULL,
	"advisory_id" text NOT NULL,
	"source" text NOT NULL,
	"severity" text NOT NULL,
	"summary" text DEFAULT '' NOT NULL,
	"position" integer NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "dependency_advisories_id_workspace_unique" UNIQUE("id","workspace_id"),
	CONSTRAINT "dependency_advisories_dependency_advisory_source_unique" UNIQUE("dependency_id","advisory_id","source"),
	CONSTRAINT "dependency_advisories_source_allowed" CHECK ("dependency_advisories"."source" in ('manual', 'osv')),
	CONSTRAINT "dependency_advisories_severity_allowed" CHECK ("dependency_advisories"."severity" in ('critical', 'high', 'medium', 'low', 'unknown'))
);
--> statement-breakpoint
CREATE TABLE "dependency_advisory_aliases" (
	"workspace_id" uuid NOT NULL,
	"advisory_row_id" uuid NOT NULL,
	"alias" text NOT NULL,
	"position" integer NOT NULL,
	CONSTRAINT "dependency_advisory_aliases_pk" PRIMARY KEY("advisory_row_id","alias")
);
--> statement-breakpoint
ALTER TABLE "dependency_advisories" ADD CONSTRAINT "dependency_advisories_workspace_id_workspaces_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "dependency_advisories" ADD CONSTRAINT "dependency_advisories_dependency_fk" FOREIGN KEY ("dependency_id","workspace_id") REFERENCES "public"."app_dependencies"("id","workspace_id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "dependency_advisory_aliases" ADD CONSTRAINT "dependency_advisory_aliases_workspace_id_workspaces_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "dependency_advisory_aliases" ADD CONSTRAINT "dependency_advisory_aliases_advisory_fk" FOREIGN KEY ("advisory_row_id","workspace_id") REFERENCES "public"."dependency_advisories"("id","workspace_id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
-- One-off backfill 1 of 3: each advisory the OSV check stored in the jsonb list
-- becomes a row. Ids normally come from the app (newId()); gen_random_uuid() is
-- used here only because this copy runs inside the migration.
-- Odd stored JSON is skipped, not failed on: a value that is not a list, an
-- entry that is not an object, an id that is not text, is blank or is longer
-- than 100 characters, and a second entry with an id already seen.
INSERT INTO "dependency_advisories" ("id", "workspace_id", "dependency_id", "advisory_id", "source", "severity", "summary", "position")
SELECT
	gen_random_uuid(),
	d."workspace_id",
	d."id",
	a.item->>'id',
	'osv',
	CASE WHEN a.item->>'severity' IN ('critical', 'high', 'medium', 'low') THEN a.item->>'severity' ELSE 'unknown' END,
	CASE WHEN jsonb_typeof(a.item->'summary') = 'string' THEN left(a.item->>'summary', 300) ELSE '' END,
	a.ordinality - 1
FROM "app_dependencies" d
CROSS JOIN LATERAL jsonb_array_elements(
	CASE WHEN jsonb_typeof(d."advisories") = 'array' THEN d."advisories" ELSE '[]'::jsonb END
) WITH ORDINALITY AS a(item, ordinality)
WHERE jsonb_typeof(a.item) = 'object'
	AND jsonb_typeof(a.item->'id') = 'string'
	AND btrim(a.item->>'id') <> ''
	AND length(a.item->>'id') <= 100
ORDER BY d."id", a.ordinality
ON CONFLICT DO NOTHING;--> statement-breakpoint
-- One-off backfill 2 of 3: the other ids of each copied advisory. Entries that
-- are not text, are blank or are longer than 100 characters are skipped.
INSERT INTO "dependency_advisory_aliases" ("workspace_id", "advisory_row_id", "alias", "position")
SELECT r."workspace_id", r."id", al.item #>> '{}', al.ordinality - 1
FROM "app_dependencies" d
CROSS JOIN LATERAL jsonb_array_elements(
	CASE WHEN jsonb_typeof(d."advisories") = 'array' THEN d."advisories" ELSE '[]'::jsonb END
) AS a(item)
JOIN "dependency_advisories" r
	ON r."dependency_id" = d."id" AND r."source" = 'osv' AND r."advisory_id" = a.item->>'id'
CROSS JOIN LATERAL jsonb_array_elements(
	CASE WHEN jsonb_typeof(a.item->'aliases') = 'array' THEN a.item->'aliases' ELSE '[]'::jsonb END
) WITH ORDINALITY AS al(item, ordinality)
WHERE jsonb_typeof(a.item->'id') = 'string'
	AND jsonb_typeof(al.item) = 'string'
	AND btrim(al.item #>> '{}') <> ''
	AND length(al.item #>> '{}') <= 100
ORDER BY r."id", al.ordinality
ON CONFLICT DO NOTHING;--> statement-breakpoint
-- One-off backfill 3 of 3: each advisory id recorded by hand becomes a row.
-- Blank ids, ids longer than 100 characters and repeats are skipped.
INSERT INTO "dependency_advisories" ("id", "workspace_id", "dependency_id", "advisory_id", "source", "severity", "position")
SELECT gen_random_uuid(), d."workspace_id", d."id", v.advisory_id, 'manual', 'unknown', v.ordinality - 1
FROM "app_dependencies" d
CROSS JOIN LATERAL unnest(d."vulnerabilities") WITH ORDINALITY AS v(advisory_id, ordinality)
WHERE btrim(v.advisory_id) <> ''
	AND length(v.advisory_id) <= 100
ORDER BY d."id", v.ordinality
ON CONFLICT DO NOTHING;--> statement-breakpoint
ALTER TABLE "app_dependencies" DROP COLUMN "vulnerabilities";--> statement-breakpoint
ALTER TABLE "app_dependencies" DROP COLUMN "advisories";
